const page = await browser.getPage("main");
const errors = [];
page.on("pageerror", (err) => errors.push(String(err)));
await page.reload({ waitUntil: "networkidle" });
await page.waitForTimeout(300);
await page.keyboard.press("Meta+a");
await page.keyboard.press("Backspace");
await page.waitForTimeout(100);

const box = await page.locator(".canvas-wrap").boundingBox();
if (!box) throw new Error("no canvas");
const start = { x: box.x + 220, y: box.y + 180 };
const end = { x: start.x + 180, y: start.y + 110 };

await page.getByRole("button", { name: "Rectangle (R)" }).click();
await page.mouse.move(start.x, start.y);
await page.mouse.down();
await page.mouse.move(end.x, end.y, { steps: 12 });
await page.mouse.up();
await page.waitForTimeout(250);

const nums = await page.locator(".num input").evaluateAll((els) => els.slice(0, 6).map((el) => el.value));
const layerText = await page.locator("body").innerText();
const shot = await page.screenshot();
const path = await saveScreenshot(shot, "figma-rect2.png");
console.log(JSON.stringify({ errors, nums, path, hasRect: layerText.includes("Rectangle"), status: layerText.split("\n").slice(-6) }, null, 2));
EOF

