:root {
  color-scheme: dark;
  --ink: #121216;
  --panel: #1b1b21;
  --raised: #24242c;
  --line: #32323c;
  --text: #f2f2f6;
  --dim: #9a9aa6;
  --faint: #6d6d7a;
  --accent: #4c7dff;
