  --danger: #ff5d73;
  --canvas: #e4e4ea;
  --font: "IBM Plex Sans", "Avenir Next", sans-serif;
  --mono: "JetBrains Mono", ui-monospace, monospace;
  --toolbar: 48px;
  --status: 28px;
  --left: 252px;
  --right: 276px;
}

* { box-sizing: border-box; }
html, body, #root { height: 100%; margin: 0; }
body {
  font-family: var(--font);
  background: var(--ink);
  color: var(--text);
  overflow: hidden;
}
button, input, select, textarea { font: inherit; color: inherit; }
button { cursor: pointer; }
button:disabled { opacity: 0.4; cursor: default; }
button:focus-visible, input:focus-visible, select:focus-visible, textarea:focus-visible {
  outline: 1px solid var(--accent);
  outline-offset: 1px;
}

.app {
  height: 100%;
  display: grid;
  grid-template-rows: var(--toolbar) 1fr var(--status);
}
.workspace {
  display: grid;
  grid-template-columns: var(--left) 1fr var(--right);
  min-height: 0;
}
.toolbar {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0 10px;
  background: var(--panel);
  border-bottom: 1px solid var(--line);
  position: relative;
}
.toolbar h1 {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: -0.02em;
}
.doc-name {
  width: 140px;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 6px;
  padding: 4px 6px;
  color: var(--dim);
}
.doc-name:hover, .doc-name:focus { border-color: var(--line); background: var(--raised); }
.tools { display: flex; gap: 2px; margin-left: 8px; }
.tool, .quiet, .zoom, .primary, .align-row button, .panel-tabs button, .pages button {
  background: transparent;
  border: 1px solid transparent;
  border-radius: 7px;
  color: var(--text);
}
.tool {
