}
.tool:hover, .quiet:hover, .align-row button:hover { background: var(--raised); }
.tool.on { background: var(--accent-dim); color: #9db6ff; }
.toolbar-actions { margin-left: auto; display: flex; align-items: center; gap: 6px; }
.quiet, .zoom, .primary { padding: 5px 8px; font-size: 12px; }
.zoom { min-width: 58px; background: var(--raised); border-color: var(--line); }
.primary { background: var(--accent); color: white; border-color: transparent; font-weight: 600; }
.panel {
  background: var(--panel);
  min-height: 0;
  display: flex;
  flex-direction: column;
}
.panel.left { border-right: 1px solid var(--line); }
.panel.right { border-left: 1px solid var(--line); overflow: auto; }
.panel-tabs, .pages { display: flex; gap: 4px; padding: 8px; }
.panel-tabs button, .pages button { padding: 4px 8px; font-size: 12px; color: var(--dim); }
.panel-tabs button.on, .pages button.on { color: var(--text); background: var(--raised); }
.search, .rename, .num input, .num select, .picker input, .modal input {
  width: 100%;
  background: var(--ink);
  border: 1px solid var(--line);
