}
.search { margin: 0 8px 8px; width: auto; }
.layer-scroll { overflow: auto; flex: 1; }
.layer {
  display: grid;
  grid-template-columns: 14px 1fr auto auto;
  gap: 4px;
  align-items: center;
  min-height: 28px;
