.canvas-wrap { position: relative; min-width: 0; min-height: 0; background: var(--canvas); }
.scene, .overlay { position: absolute; inset: 0; width: 100%; height: 100%; }
.overlay { pointer-events: none; }
.text-editor {
  position: absolute;
  left: 0;
  top: 0;
  margin: 0;
  border: 1px dashed #4c7dff;
  background: transparent;
  color: #16161a;
  caret-color: #16161a;
  resize: none;
  overflow: hidden;
  padding: 0;
  z-index: 2;
}
.status {
  display: flex;
  justify-content: flex-end;
  gap: 16px;
  align-items: center;
  padding: 0 12px;
  font-size: 11px;
  color: var(--dim);
  background: var(--panel);
  border-top: 1px solid var(--line);
  font-variant-numeric: tabular-nums;
}
.menu {
  position: fixed;
  z-index: 20;
  background: var(--raised);
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 6px;
  min-width: 180px;
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.35);
  display: flex;
  flex-direction: column;
}
.menu.pop { top: 44px; right: 12px; }
.menu.object-menu { right: 86px; }
.menu button, .file-btn {
  text-align: left;
  background: transparent;
  border: 0;
  border-radius: 6px;
  padding: 7px 8px;
  font-size: 12px;
}
.menu button:hover, .file-btn:hover { background: var(--accent-dim); }
.file-btn input { display: none; }
.picker {
  position: absolute;
  z-index: 5;
  right: 0;
  top: 24px;
  width: 210px;
  background: var(--raised);
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 8px;
  box-shadow: 0 12px 30px rgba(0,0,0,.35);
}
.sv { position: relative; height: 120px; border-radius: 8px; margin-bottom: 8px; }
.sv i { position: absolute; width: 10px; height: 10px; border: 2px solid white; border-radius: 50%; transform: translate(-50%, -50%); box-shadow: 0 0 0 1px #000; }
.hue, .alpha { width: 100%; margin: 4px 0; }
.picker-row, .recents { display: flex; gap: 6px; align-items: center; }
.recents button { width: 16px; height: 16px; border-radius: 4px; border: 1px solid var(--line); padding: 0; }
.toasts { position: fixed; left: 50%; bottom: 40px; transform: translateX(-50%); display: flex; flex-direction: column; gap: 6px; z-index: 30; }
.toast { background: var(--text); color: var(--ink); border-radius: 8px; padding: 8px 12px; font-size: 12px; }
.modal-back { position: fixed; inset: 0; background: rgba(0,0,0,.45); display: grid; place-items: center; z-index: 40; }
.modal { width: min(560px, calc(100% - 32px)); background: var(--panel); border: 1px solid var(--line); border-radius: 14px; padding: 16px; }
.modal h2 { margin: 0 0 12px; font-size: 16px; }
.shortcut-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px 16px; font-size: 12px; }
.shortcut-grid div { display: flex; justify-content: space-between; gap: 8px; }
kbd { font-family: var(--mono); font-size: 11px; color: var(--dim); }
.style-row { display: flex; align-items: center; gap: 8px; width: 100%; background: transparent; border: 0; color: var(--text); padding: 6px 0; font-size: 12px; }
.style-row i { width: 14px; height: 14px; border-radius: 4px; display: block; }
.play { position: fixed; inset: 0; background: #0e0e12; z-index: 35; display: grid; grid-template-rows: 44px 1fr; }
